import Foundation

public struct VivoMDPackedSystem:Sendable{
    public struct Bond:Sendable{public var atoms:SIMD2<UInt32>;public var parameters:SIMD2<Float>}
    public struct Angle:Sendable{public var atoms:SIMD4<UInt32>;public var parameters:SIMD2<Float>}
    public struct Torsion:Sendable{public var atoms:SIMD4<UInt32>;public var parameters:SIMD4<Float>}
    public struct Constraint:Sendable{public var atoms:SIMD2<UInt32>;public var distanceNM:Float}
    public struct PairException:Sendable{public var atoms:SIMD2<UInt32>;public var scales:SIMD2<Float>;public var overrideC12C6:SIMD2<Float>;public var flags:UInt32}
    public struct Incidence:Sendable{public var termIndex:UInt32;public var localIndex:UInt32}
    /// 48-byte fixed record: site/count, four parents, four weights.
    public struct LinearVirtualSite:Sendable{public var siteAndCount:SIMD2<UInt32>;public var parents:SIMD4<UInt32>;public var weights:SIMD4<Float>}
    public struct VirtualParentIncidence:Sendable{public var siteIndex:UInt32;public var weight:Float}

    public let systemFingerprint:VivoFingerprint;public let particleCount:UInt32;public let typeCount:UInt32
    public let particleDynamics:[SIMD4<Float>];public let particleTypeIndices:[UInt32];public let typePairC12C6:[SIMD2<Float>]
    public let bonds:[Bond];public let angles:[Angle];public let torsions:[Torsion];public let constraints:[Constraint]
    public let pairExceptions:[PairException];public let exceptionOffsets:[UInt32];public let exceptionPartners:[UInt32];public let exceptionIndices:[UInt32]
    public let bondOffsets:[UInt32];public let bondIncidence:[Incidence];public let angleOffsets:[UInt32];public let angleIncidence:[Incidence];public let torsionOffsets:[UInt32];public let torsionIncidence:[Incidence]
    public let virtualSites:[LinearVirtualSite];public let virtualSiteIndexByParticle:[UInt32];public let virtualParentOffsets:[UInt32];public let virtualParentIncidence:[VirtualParentIncidence]
}

public enum VivoMDSystemPacker{
    public static func pack(_ system:VivoClassicalSystem)throws->VivoMDPackedSystem{
        try VivoClassicalSystemValidator.validate(system);guard system.particles.count<=Int(UInt32.max)else{throw VivoArtifactValidationError.invalid("MD particle count exceeds UInt32 execution ABI")}
