        let torsions=try system.torsions.map{Torsion(atoms:.init($0.a,$0.b,$0.c,$0.d),parameters:.init(Float($0.periodicity),try ff($0.phaseRadians,"torsion phase"),try ff($0.barrierKJPerMol,"torsion barrier"),$0.improper ? 1:0))}
        let constraints=try system.constraints.map{Constraint(atoms:.init($0.a,$0.b),distanceNM:try ff($0.distanceNM,"constraint distance"))}
        let exceptions=try system.nonbondedExceptions.map{v->PairException in var ov=SIMD2<Float>.zero,flags:UInt32=0;if v.sigmaOverrideNM != nil || v.epsilonOverrideKJPerMol != nil{guard let s=v.sigmaOverrideNM,let e=v.epsilonOverrideKJPerMol else{throw VivoArtifactValidationError.invalid("nonbonded exception must provide both sigma and epsilon overrides")};ov=try lj(s,e);flags=1};return .init(atoms:.init(v.a,v.b),scales:.init(try ff(v.coulombScale,"exception Coulomb scale"),try ff(v.lennardJonesScale,"exception LJ scale")),overrideC12C6:ov,flags:flags)}.sorted{pairKey($0.atoms.x,$0.atoms.y)<pairKey($1.atoms.x,$1.atoms.y)}
