    }

    private static func packVirtualSites(_ source:[VivoLinearVirtualSite],particleCount:Int)throws->(sites:[VivoMDPackedSystem.LinearVirtualSite],mapping:[UInt32],offsets:[UInt32],incidence:[VivoMDPackedSystem.VirtualParentIncidence]){
        var sites:[VivoMDPackedSystem.LinearVirtualSite]=[],mapping=[UInt32](repeating:UInt32.max,count:particleCount),buckets=[[VivoMDPackedSystem.VirtualParentIncidence]](repeating:[],count:particleCount)
