        var offsets:[UInt32]=[0],incidence:[VivoMDPackedSystem.VirtualParentIncidence]=[];for bucket in buckets{incidence.append(contentsOf:bucket);guard let next=UInt32(exactly:incidence.count)else{throw VivoArtifactValidationError.invalid("virtual parent incidence exceeds UInt32")};offsets.append(next)};return(sites,mapping,offsets,incidence)
    }
    private static func compilePairMatrix(system:VivoClassicalSystem,typeNames:[String])throws->[SIMD2<Float>]{var by:[String:VivoClassicalParticle]=[:];for p in system.particles where by[p.typeIdentifier]==nil{by[p.typeIdentifier]=p};let n=typeNames.count;var out=[SIMD2<Float>](repeating:.zero,count:n*n);if system.mixingRule == .explicitPairTable{guard let pairs=system.nonbondedTypePairs else{throw VivoArtifactValidationError.invalid("explicit pair table disappeared after validation")};var lookup:[String:VivoNonbondedTypePair]=[:];for p in pairs{lookup[typePairKey(p.typeA,p.typeB)]=p};for i in 0..<n{for j in i..<n{guard let p=lookup[typePairKey(typeNames[i],typeNames[j])]else{throw VivoArtifactValidationError.invalid("explicit pair table is incomplete during MD packing")};let v=SIMD2<Float>(try ff(p.c12KJNM12PerMol,"C12"),try ff(p.c6KJNM6PerMol,"C6"));out[i*n+j]=v;out[j*n+i]=v}};return out};for i in 0..<n{guard let l=by[typeNames[i]]else{throw VivoArtifactValidationError.invalid("missing representative type")};for j in i..<n{guard let r=by[typeNames[j]]else{throw VivoArtifactValidationError.invalid("missing representative type")};let sigma:Double,epsilon=sqrt(l.epsilonKJPerMol*r.epsilonKJPerMol);switch system.mixingRule{case .lorentzBerthelot:sigma=0.5*(l.sigmaNM+r.sigmaNM);case .geometric:sigma=sqrt(l.sigmaNM*r.sigmaNM);case .explicitPairTable:preconditionFailure()};let v=try lj(sigma,epsilon);out[i*n+j]=v;out[j*n+i]=v}};return out}
    private static func lj(_ sigma:Double,_ epsilon:Double)throws->SIMD2<Float>{guard sigma.isFinite,sigma>=0,epsilon.isFinite,epsilon>=0 else{throw VivoArtifactValidationError.invalid("LJ sigma/epsilon is invalid")};if sigma==0||epsilon==0{return .zero};let s6=pow(sigma,6),c6=4*epsilon*s6,c12=c6*s6;return .init(try ff(c12,"derived C12"),try ff(c6,"derived C6"))}
    private static func ff(_ value:Double,_ label:String)throws->Float{guard value.isFinite,abs(value)<=Double(Float.greatestFiniteMagnitude)else{throw VivoArtifactValidationError.invalid("\(label) cannot be represented by Wave B FP32")};let f=Float(value);if value != 0,f==0{throw VivoArtifactValidationError.invalid("\(label) underflows Wave B FP32")};return f}
    private static func typePairKey(_ a:String,_ b:String)->String{a<=b ? a+"\u{0}"+b:b+"\u{0}"+a};private static func pairKey(_ a:UInt32,_ b:UInt32)->UInt64{UInt64(min(a,b))<<32|UInt64(max(a,b))}
    private static func incidence(termCount:Int,particleCount:Int,members:(Int)->[(UInt32,UInt32)])throws->(offsets:[UInt32],entries:[VivoMDPackedSystem.Incidence]){var buckets=[[VivoMDPackedSystem.Incidence]](repeating:[],count:particleCount);for t in 0..<termCount{guard let ti=UInt32(exactly:t)else{throw VivoArtifactValidationError.invalid("MD term count exceeds UInt32")};for(p,l)in members(t){guard p<UInt32(particleCount)else{throw VivoArtifactValidationError.invalid("MD incidence references absent particle")};buckets[Int(p)].append(.init(termIndex:ti,localIndex:l))}};var offsets:[UInt32]=[0],entries:[VivoMDPackedSystem.Incidence]=[];for b in buckets{entries.append(contentsOf:b);guard let n=UInt32(exactly:entries.count)else{throw VivoArtifactValidationError.invalid("MD incidence exceeds UInt32")};offsets.append(n)};return(offsets,entries)}
    private static func pairAdjacency(_ values:[VivoMDPackedSystem.PairException],particleCount:Int)throws->(offsets:[UInt32],partners:[UInt32],indices:[UInt32]){var buckets=[[(UInt32,UInt32)]](repeating:[],count:particleCount);for(i,v)in values.enumerated(){guard let ix=UInt32(exactly:i),v.atoms.x<UInt32(particleCount),v.atoms.y<UInt32(particleCount)else{throw VivoArtifactValidationError.invalid("MD exception adjacency exceeds ABI")};buckets[Int(v.atoms.x)].append((v.atoms.y,ix));buckets[Int(v.atoms.y)].append((v.atoms.x,ix))};var o:[UInt32]=[0],p:[UInt32]=[],idx:[UInt32]=[];for var b in buckets{b.sort{$0.0<$1.0};for x in b{p.append(x.0);idx.append(x.1)};guard let n=UInt32(exactly:p.count)else{throw VivoArtifactValidationError.invalid("MD exception adjacency exceeds UInt32")};o.append(n)};return(o,p,idx)}
}
